pub const CONTRACT_VERSION: &str = "conformance-multimodal-context-compilation-assurance/1.0";
pub const INPUT_SCHEMA: &str = "DecisionQuery2@1";
pub const OUTPUT_SCHEMA: &str = "CertifiedDecisionSection7@1";
pub const CONTENT_TYPE: &str = "application/vnd.aurora.certified-decision-section-7+json";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DecisionQuery2 { pub schema_version:String, pub request_id:String, pub consumer:String, pub federation_id:String, pub purpose:String, pub semantic_profile:String, pub target_schema:String, pub required_fact_order:Vec<String>, pub required_study_order:Vec<String>, pub required_modality_order:Vec<String>, pub required_peer_order:Vec<String>, pub replay_identity:ContentHash, pub policy_allow:bool, pub protected_closure:bool, pub raw_data_local:bool, pub aggregate_only:bool, pub budget_units:u64, pub adversarial_event_order:Vec<String>, pub boundary:String }
