pub struct DecisionFact2 { pub fact_id:String, pub study_id:String, pub modality:String, pub semantic_profile:String, pub influence_milli:u16, pub evidence_state:EvidenceState, pub artifact_digest:ContentHash, pub provenance_digest:ContentHash, pub replay_identity:ContentHash, pub permitted:bool, pub raw_data_local:bool, pub aggregate_only:bool, pub omission_order:Vec<String>, pub uncertainty_order:Vec<String>, pub negative_result:bool }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContextPeer2 { pub peer_id:String, pub study_order:Vec<String>, pub modality_order:Vec<String>, pub semantic_profile:String, pub replay_identity:ContentHash, pub evidence_state:EvidenceState, pub signed:bool, pub permitted:bool, pub raw_data_local:bool, pub aggregate_only:bool, pub omission_order:Vec<String>, pub uncertainty_order:Vec<String>, pub negative_result:bool }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CertifiedDecisionSection7Artifact { pub artifact_id:String, pub content_type:String, pub content_hash:ContentHash, pub semantic_loss:Vec<String>, pub provenance_digests:Vec<ContentHash>, pub boundary:String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CertifiedDecisionSection7 { pub schema_version:String, pub contract_version:String, pub feature_id:String, pub request_id:String, pub consumer:String, pub federation_id:String, pub purpose:String, pub semantic_profile:String, pub target_schema:String, pub disposition:String, pub fact_order:Vec<String>, pub selected_fact_order:Vec<String>, pub unresolved_fact_order:Vec<String>, pub blocked_fact_order:Vec<String>, pub missing_fact_order:Vec<String>, pub study_order:Vec<String>, pub selected_study_order:Vec<String>, pub missing_study_order:Vec<String>, pub modality_order:Vec<String>, pub selected_modality_order:Vec<String>, pub missing_modality_order:Vec<String>, pub peer_order:Vec<String>, pub qualified_peer_order:Vec<String>, pub missing_peer_order:Vec<String>, pub omission_order:Vec<String>, pub uncertainty_order:Vec<String>, pub negative_evidence_order:Vec<String>, pub replay_identity:ContentHash, pub section_digest:ContentHash, pub artifact:CertifiedDecisionSection7Artifact, pub effect_receipts:Vec<String>, pub raw_data_local:bool, pub aggregate_only:bool, pub boundary:String }
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum ContextCompilationAssuranceError { #[error("invalid context-compilation assurance request: {0}")] Invalid(String), #[error("context-compilation assurance artifact failed: {0}")] Artifact(String) }
fn hash_ok(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())} fn ordered(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])} fn digest(v:&Value)->Result<ContentHash,ContextCompilationAssuranceError>{ContentHash::of_value(v).map_err(|e|ContextCompilationAssuranceError::Artifact(e.to_string()))}
pub fn context_compilation_assurance_manifest()->CapabilityManifest{CapabilityManifest{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),capability_id:FEATURE_ID.into(),version:CONTRACT_VERSION.into(),owner_crate:"conformance".into(),consumers:["consortium operator".into(),"context compiler".into(),"release reviewer".into()].into(),behavior:"verifies multimodal multi-study decision facts and peer summaries into an omission-aware certified section".into(),value:"prevents semantic mismatch, incomplete closure, and contradictory evidence from becoming an asserted decision context".into(),inputs:vec![TypedPort{name:"decision_query".into(),schema:INPUT_SCHEMA.into(),required:true}],outputs:vec![TypedPort{name:"certified_decision_section".into(),schema:OUTPUT_SCHEMA.into(),required:true}],effects:[Effect::ExecuteLocalComputation,Effect::WriteLocalArtifact].into(),permissions:["evaluate:capability-runs".into()].into(),determinism:Determinism::ByteStable,evidence:vec![EvidenceReference{source_id:"slsa-provenance-1.2".into(),state:EvidenceState::Supported,locator:Some("https://slsa.dev/spec/v1.2/provenance".into())}],authority_requirements:Vec::new(),autonomy_tier:AutonomyTier::A1,surfaces:[ResearchSurface::Ui,ResearchSurface::Api,ResearchSurface::Sdk,ResearchSurface::Cli,ResearchSurface::McpTool,ResearchSurface::Policy,ResearchSurface::Operator].into(),boundary:PRECLINICAL_BOUNDARY.into()}}
impl CertifiedDecisionSection7{pub fn validate(&self)->Result<(),ContextCompilationAssuranceError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.consumer.trim().is_empty()||self.federation_id.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||self.target_schema.trim().is_empty()||self.fact_order.is_empty()||self.study_order.is_empty()||self.modality_order.is_empty()||self.peer_order.is_empty()||self.effect_receipts!=vec!["block:unsafe-release"]{return Err(ContextCompilationAssuranceError::Invalid("context identity, closure, locality, or release gate is incomplete".into()));}for v in [&self.fact_order,&self.selected_fact_order,&self.unresolved_fact_order,&self.blocked_fact_order,&self.missing_fact_order,&self.study_order,&self.selected_study_order,&self.missing_study_order,&self.modality_order,&self.selected_modality_order,&self.missing_modality_order,&self.peer_order,&self.qualified_peer_order,&self.missing_peer_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.effect_receipts]{if !ordered(v){return Err(ContextCompilationAssuranceError::Invalid("context ordering is not canonical".into()));}}let ids=BTreeSet::from_iter(self.fact_order.iter().cloned());let parts=self.selected_fact_order.iter().chain(&self.unresolved_fact_order).chain(&self.blocked_fact_order).chain(&self.missing_fact_order).cloned().collect::<BTreeSet<_>>();if ids.len()!=self.fact_order.len()||parts!=ids{return Err(ContextCompilationAssuranceError::Invalid("fact outcomes do not partition".into()));}for (all,parts) in [(&self.study_order,self.selected_study_order.iter().chain(&self.missing_study_order).cloned().collect::<BTreeSet<_>>()),(&self.modality_order,self.selected_modality_order.iter().chain(&self.missing_modality_order).cloned().collect::<BTreeSet<_>>()),(&self.peer_order,self.qualified_peer_order.iter().chain(&self.missing_peer_order).cloned().collect::<BTreeSet<_>>())]{if BTreeSet::from_iter(all.iter().cloned())!=parts{return Err(ContextCompilationAssuranceError::Invalid("context axes do not partition".into()));}}if !hash_ok(&self.replay_identity)||!hash_ok(&self.section_digest)||self.artifact.content_hash!=self.section_digest||self.artifact.content_type!=CONTENT_TYPE||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(ContextCompilationAssuranceError::Artifact("context artifact metadata or digest is inconsistent".into()));}Ok(())}}
pub fn assure_context_compilation(request:&DecisionQuery2,facts:&[DecisionFact2],peers:&[ContextPeer2])->Result<CertifiedDecisionSection7,ContextCompilationAssuranceError>{if request.schema_version!=INPUT_SCHEMA||request.request_id.trim().is_empty()||request.consumer.trim().is_empty()||request.federation_id.trim().is_empty()||request.purpose.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.target_schema.trim().is_empty()||request.required_fact_order.is_empty()||request.required_study_order.is_empty()||request.required_modality_order.is_empty()||request.required_peer_order.is_empty()||!ordered(&request.required_fact_order)||!ordered(&request.required_study_order)||!ordered(&request.required_modality_order)||!ordered(&request.required_peer_order)||!hash_ok(&request.replay_identity)||request.budget_units==0||!request.raw_data_local||!request.aggregate_only||request.boundary!=PRECLINICAL_BOUNDARY||facts.is_empty()||peers.is_empty(){return Err(ContextCompilationAssuranceError::Invalid("context identity, closure, digest, budget, locality, or boundary is invalid".into()));}let mut rows=facts.to_vec();rows.sort_by(|a,b|b.influence_milli.cmp(&a.influence_milli).then(a.fact_id.cmp(&b.fact_id)));let mut ids=rows.iter().map(|f|f.fact_id.clone()).collect::<Vec<_>>();let required=request.required_fact_order.iter().filter(|id|!ids.contains(id)).cloned().collect::<Vec<_>>();ids.extend(required.clone());ids.sort();ids.dedup();let mut s=BTreeSet::new();let mut u=BTreeSet::new();let mut b=BTreeSet::new();let mut m=BTreeSet::new();let mut studies=BTreeSet::new();let mut modalities=BTreeSet::new();let mut selected_studies=BTreeSet::new();let mut selected_modalities=BTreeSet::new();let mut om=BTreeSet::new();let mut un=BTreeSet::new();let mut neg=BTreeSet::new();let mut prov=BTreeSet::new();for f in &rows{studies.insert(f.study_id.clone());modalities.insert(f.modality.clone());prov.insert(f.provenance_digest.clone());om.extend(f.omission_order.iter().map(|x|format!("{}:{x}",f.fact_id)));un.extend(f.uncertainty_order.iter().map(|x|format!("{}:{x}",f.fact_id)));if f.negative_result||matches!(f.evidence_state,EvidenceState::Contradicted){neg.insert(format!("{}:negative-result",f.fact_id));}if !request.required_fact_order.contains(&f.fact_id){u.insert(f.fact_id.clone());}else if !f.permitted||!f.raw_data_local||!f.aggregate_only||f.semantic_profile!=request.semantic_profile||f.replay_identity!=request.replay_identity{b.insert(f.fact_id.clone());}else if matches!(f.evidence_state,EvidenceState::Proven|EvidenceState::Supported)&&f.influence_milli>=600{s.insert(f.fact_id.clone());selected_studies.insert(f.study_id.clone());selected_modalities.insert(f.modality.clone());}else{u.insert(f.fact_id.clone());}}for id in &required{if !rows.iter().any(|f|&f.fact_id==id){m.insert(id.clone());om.insert(format!("required:{id}"));}}let mut peer_rows=peers.to_vec();peer_rows.sort_by(|a,b|a.peer_id.cmp(&b.peer_id));let peer_ids=peer_rows.iter().map(|p|p.peer_id.clone()).collect::<Vec<_>>();let mut qp=BTreeSet::new();let mut mp=BTreeSet::new();for p in &peer_rows{if p.semantic_profile==request.semantic_profile&&p.signed&&p.permitted&&p.raw_data_local&&p.aggregate_only&&p.replay_identity==request.replay_identity&&matches!(p.evidence_state,EvidenceState::Proven|EvidenceState::Supported){qp.insert(p.peer_id.clone());}else{mp.insert(p.peer_id.clone());om.extend(p.omission_order.iter().map(|x|format!("{}:{x}",p.peer_id)));un.extend(p.uncertainty_order.iter().map(|x|format!("{}:{x}",p.peer_id)));if p.negative_result{neg.insert(format!("{}:negative-result",p.peer_id));}}}let global=!request.policy_allow||!request.protected_closure||!request.raw_data_local||!request.aggregate_only||!request.adversarial_event_order.is_empty();if global{b.extend(ids.iter().cloned());s.clear();u.clear();m.clear();om.insert("request:governance-or-adversarial-blocked".into());}un.extend(request.adversarial_event_order.iter().map(|e|format!("adversarial:{e}")));let missing_studies=request.required_study_order.iter().filter(|x|!selected_studies.contains(*x)).cloned().collect::<BTreeSet<_>>();let missing_modalities=request.required_modality_order.iter().filter(|x|!selected_modalities.contains(*x)).cloned().collect::<BTreeSet<_>>();let disposition=if global{"blocked"}else if !u.is_empty()||!b.is_empty()||!m.is_empty()||qp.len()<request.required_peer_order.len(){"unresolved"}else{"qualified"};if disposition!="qualified"{om.insert("request:context-closure-not-ready".into());}let payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.request_id,"consumer":request.consumer,"federation_id":request.federation_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"target_schema":request.target_schema,"disposition":disposition,"fact_order":ids,"selected_fact_order":s.iter().cloned().collect::<Vec<_>>(),"unresolved_fact_order":u.iter().cloned().collect::<Vec<_>>(),"blocked_fact_order":b.iter().cloned().collect::<Vec<_>>(),"missing_fact_order":m.iter().cloned().collect::<Vec<_>>(),"study_order":studies.iter().cloned().collect::<Vec<_>>(),"selected_study_order":selected_studies.iter().cloned().collect::<Vec<_>>(),"missing_study_order":missing_studies.iter().cloned().collect::<Vec<_>>(),"modality_order":modalities.iter().cloned().collect::<Vec<_>>(),"selected_modality_order":selected_modalities.iter().cloned().collect::<Vec<_>>(),"missing_modality_order":missing_modalities.iter().cloned().collect::<Vec<_>>(),"peer_order":peer_ids,"qualified_peer_order":qp.iter().cloned().collect::<Vec<_>>(),"missing_peer_order":mp.iter().cloned().collect::<Vec<_>>(),"omission_order":om.iter().cloned().collect::<Vec<_>>(),"uncertainty_order":un.iter().cloned().collect::<Vec<_>>(),"negative_evidence_order":neg.iter().cloned().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=digest(&payload)?;let artifact=CertifiedDecisionSection7Artifact{artifact_id:format!("certified-decision-section-7:{}",request.request_id),content_type:CONTENT_TYPE.into(),content_hash:d.clone(),semantic_loss:payload["omission_order"].as_array().unwrap().iter().filter_map(|v|v.as_str().map(String::from)).collect(),provenance_digests:prov.into_iter().collect(),boundary:PRECLINICAL_BOUNDARY.into()};let out=CertifiedDecisionSection7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:request.request_id.clone(),consumer:request.consumer.clone(),federation_id:request.federation_id.clone(),purpose:request.purpose.clone(),semantic_profile:request.semantic_profile.clone(),target_schema:request.target_schema.clone(),disposition:disposition.into(),fact_order:payload["fact_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),selected_fact_order:payload["selected_fact_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),unresolved_fact_order:payload["unresolved_fact_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),blocked_fact_order:payload["blocked_fact_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_fact_order:payload["missing_fact_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),study_order:payload["study_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),selected_study_order:payload["selected_study_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_study_order:payload["missing_study_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),modality_order:payload["modality_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),selected_modality_order:payload["selected_modality_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_modality_order:payload["missing_modality_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),peer_order:payload["peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),qualified_peer_order:payload["qualified_peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_peer_order:payload["missing_peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),omission_order:payload["omission_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),uncertainty_order:payload["uncertainty_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),negative_evidence_order:payload["negative_evidence_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),replay_identity:request.replay_identity.clone(),section_digest:d,artifact,effect_receipts:vec!["block:unsafe-release".into()],raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn q()->DecisionQuery2{let h=h("ctx");DecisionQuery2{schema_version:INPUT_SCHEMA.into(),request_id:"r".into(),consumer:"consortium-operator".into(),federation_id:"f".into(),purpose:"context".into(),semantic_profile:"p".into(),target_schema:OUTPUT_SCHEMA.into(),required_fact_order:vec!["fact".into()],required_study_order:vec!["study".into()],required_modality_order:vec!["imaging".into()],required_peer_order:vec!["peer".into()],replay_identity:h,policy_allow:true,protected_closure:true,raw_data_local:true,aggregate_only:true,budget_units:8,adversarial_event_order:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}fn f()->DecisionFact2{let h=h("ctx");DecisionFact2{fact_id:"fact".into(),study_id:"study".into(),modality:"imaging".into(),semantic_profile:"p".into(),influence_milli:800,evidence_state:EvidenceState::Supported,artifact_digest:h.clone(),provenance_digest:h.clone(),replay_identity:h,permitted:true,raw_data_local:true,aggregate_only:true,omission_order:vec![],uncertainty_order:vec![],negative_result:false}}fn p()->ContextPeer2{let h=h("ctx");ContextPeer2{peer_id:"peer".into(),study_order:vec!["study".into()],modality_order:vec!["imaging".into()],semantic_profile:"p".into(),replay_identity:h,evidence_state:EvidenceState::Supported,signed:true,permitted:true,raw_data_local:true,aggregate_only:true,omission_order:vec![],uncertainty_order:vec![],negative_result:false}}#[test]fn manifest_a1(){assert_eq!(context_compilation_assurance_manifest().autonomy_tier,AutonomyTier::A1)}#[test]fn release_gate_is_explicit(){let r=assure_context_compilation(&q(),&[f()],&[p()]).unwrap();assert_eq!(r.effect_receipts,vec!["block:unsafe-release"])}#[test]fn adversarial_blocks(){let mut x=q();x.adversarial_event_order=vec!["poisoned-context".into()];assert_eq!(assure_context_compilation(&x,&[f()],&[p()]).unwrap().disposition,"blocked")}}


